    public static JSONObject install(){JSONObject out=new JSONObject();JSONArray failed=new JSONArray();int ok=0;try{
        for(String s:SPELLS){if(registerSpell(s))ok++;else failed.put(s);}return out.put("installed_spells",ok).put("expected_spells",SPELLS.length).put("complete",ok==SPELLS.length).put("failed",failed).put("auto_rolls",false).put("surface_language","pt-BR");
    }catch(Exception e){try{return out.put("installed_spells",ok).put("complete",false).put("failed",failed);}catch(Exception ignored){return out;}}}
    private static boolean registerSpell(String name){try{JSONObject ev=new JSONObject().put("evidence_id","run144.au.spell."+id(name)).put("content_kind","spell").put("content_name",name).put("source_book",SOURCE).put("source_locator","5e.tools AU structured spell data reviewed 2026-09-29").put("revision",1);if(!AuthorizedMechanicalEvidenceRegistry.registerReviewed(ev).optBoolean("registered",false))return false;JSONObject mech=new JSONObject().put("effect_pipeline_complete",true).put("execution_status","compiled_manual_resolution_pipeline").put("runtime_resolver","ArcanaUnleashedRun144Engine.resolveSpell").put("auto_rolls",false).put("auto_mutation_allowed",false).put("surface_language","pt-BR");return CompiledContentMechanicsEngine.register("spell",name,mech,ev).optBoolean("registered",false);}catch(Exception e){return false;}}

