    private static void meta(JSONObject o,int level,String school,String casting,String range,String duration,String effect,String manual)throws Exception{o.put("nivel",level).put("escola",school).put("tempo_conjuracao",casting).put("alcance",range).put("duracao",duration).put("efeito_resumido",effect).put("entrada_manual_necessaria",manual).put("resolucao_manual",!manual.startsWith("nenhuma"));}

    /** Duas fases: prévia sem gasto; commit_cast=true gasta slot; se houver rolagens, manual_complete finaliza sem rolar pelo sistema. */
    public static JSONObject resolveSpell(JSONObject input,String spell,int slotLevel,JSONObject payload){JSONObject s=copy(input);try{if(payload==null)payload=new JSONObject();String c=canon(SPELLS,spell);JSONObject info=spellInfo(c);if(!info.optBoolean("known",false))return spellBlocked(s,"magia_desconhecida");int min=info.optInt("nivel",0);int slot=Math.max(min,slotLevel);s.put("au_spell_preview",info).put("au_spell_auto_rolls",false).put("au_spell_surface_language","pt-BR");String pending=s.optString("au_pending_spell","");boolean resume=n(pending).equals(n(c));if(!resume&&!payload.optBoolean("commit_cast",false))return s.put("au_spell_resolved",false).put("au_spell_status","aguardando_confirmacao_de_conjuracao").put("au_spell_required_input",info.optString("entrada_manual_necessaria"));if(!resume){if(min>0&&!spendSlot(s,slot))return spellBlocked(s,"slot_de_magia_indisponivel");s.put("au_pending_spell",c).put("au_pending_spell_slot_level",slot).put("au_spell_cast_committed",true);}String required=info.optString("entrada_manual_necessaria","");boolean needs=!required.startsWith("nenhuma");if(needs&&!payload.optBoolean("manual_complete",false))return s.put("au_spell_resolved",false).put("au_spell_status","aguardando_resolucao_manual").put("au_spell_required_input",required).put("au_spell_effect",info);clearPendingSpell(s);appendEffect(s,info);return s.put("au_spell_resolved",true).put("au_spell_status","resolvida").put("au_spell_effect",info).put("au_spell_resolution_payload",payload).put("au_spell_auto_rolls",false);
    }catch(Exception e){return s;}}

